import sys
sys.stdout.reconfigure(encoding='utf-8')

with open('mode.js', 'r', encoding='utf-8', newline='') as f:
    content = f.read()

# 1. Empty state in renderCommunityPreviewsHTML
target_empty = """                    <p class="text-xs font-bold text-[#5A5550]">No community posts yet</p>\n                    <p class="text-[10.5px] text-[#8E8A85] leading-relaxed">Be the first to share with your peers in the community.</p>"""
repl_empty = """                    <p class="text-xs font-bold text-[#5A5550]">${isViLocale() ? 'Chưa có bài viết cộng đồng nào' : 'No community posts yet'}</p>\n                    <p class="text-[10.5px] text-[#8E8A85] leading-relaxed">${isViLocale() ? 'Hãy là người đầu tiên chia sẻ với bạn bè trong cộng đồng.' : 'Be the first to share with your peers in the community.'}</p>"""
assert target_empty in content, "target_empty not found in mode.js"
content = content.replace(target_empty, repl_empty, 1)

# 2. In renderDmodeHome:
target_dmode_btn = """                                <button type="button"\n                                        id="btn-see-all-posts"\n                                        onclick="window.TempoApp.navigateTo('community'); if(window.TempoCommunity) window.TempoCommunity.selectTab('posts');"\n                                        class="px-3.5 py-1 rounded-full bg-[#FCEFE8] hover:bg-[#F8E1D5] text-[#DE8662] text-xs font-bold transition flex items-center space-x-1 cursor-pointer">\n                                    <span>${(window.t ? window.t('modes.default.seeAll') : null) || (isViLocale() ? 'Xem tất cả' : 'See all')}</span>\n                                    <span>→</span>\n                                </button>"""
repl_dmode_btn = """                                <button type="button"\n                                        id="btn-see-all-posts"\n                                        onclick="window.TempoApp.navigateTo('community'); if(window.TempoCommunity) window.TempoCommunity.selectTab('posts');"\n                                        class="px-3.5 py-1 rounded-full bg-[#FCEFE8] hover:bg-[#F8E1D5] text-[#DE8662] text-xs font-bold transition flex items-center space-x-1 cursor-pointer"\n                                        aria-label="${isViLocale() ? 'Xem tất cả →' : 'View all →'}" title="${isViLocale() ? 'Xem tất cả →' : 'View all →'}">\n                                    <span>${(window.t ? (window.t('modes.default.viewAll') || window.t('modes.default.seeAll')) : null) || (isViLocale() ? 'Xem tất cả' : 'View all')}</span>\n                                    <span>→</span>\n                                </button>"""
assert target_dmode_btn in content, "target_dmode_btn not found in mode.js"
content = content.replace(target_dmode_btn, repl_dmode_btn, 1)

# 3. In renderEmodeHome:
target_emode_btn = """                    <button type="button" \n                            id="btn-see-all-posts-urgent"\n                            onclick="if (window.TempoApp && typeof window.TempoApp.navigateTo === 'function') { window.TempoApp.navigateTo('community'); } else { window.location.hash = '#community?tab=posts'; } if (window.TempoCommunity && typeof window.TempoCommunity.selectTab === 'function') { window.TempoCommunity.selectTab('posts'); }" \n                            class="px-3.5 py-1 rounded-full bg-[#FCEFE8] hover:bg-[#F8E1D5] text-[#DE8662] text-xs font-bold transition flex items-center space-x-1 cursor-pointer">\n                        <span>Xem tất cả</span>\n                        <span class="text-xs">&rarr;</span>\n                    </button>"""
repl_emode_btn = """                    <button type="button" \n                            id="btn-see-all-posts-urgent"\n                            onclick="if (window.TempoApp && typeof window.TempoApp.navigateTo === 'function') { window.TempoApp.navigateTo('community'); } else { window.location.hash = '#community?tab=posts'; } if (window.TempoCommunity && typeof window.TempoCommunity.selectTab === 'function') { window.TempoCommunity.selectTab('posts'); }" \n                            class="px-3.5 py-1 rounded-full bg-[#FCEFE8] hover:bg-[#F8E1D5] text-[#DE8662] text-xs font-bold transition flex items-center space-x-1 cursor-pointer"\n                            aria-label="${isViLocale() ? 'Xem tất cả →' : 'View all →'}" title="${isViLocale() ? 'Xem tất cả →' : 'View all →'}">\n                        <span>${(window.t ? (window.t('modes.urgent.viewAll') || window.t('modes.urgent.seeAll')) : null) || (isViLocale() ? 'Xem tất cả' : 'View all')}</span>\n                        <span class="text-xs">&rarr;</span>\n                    </button>"""
assert target_emode_btn in content, "target_emode_btn not found in mode.js"
content = content.replace(target_emode_btn, repl_emode_btn, 1)

# 4. In renderRmodeHome:
target_rmode_btn = """                    <button type="button" \n                            id="btn-see-all-posts-recovery"\n                            onclick="if (window.TempoApp && typeof window.TempoApp.navigateTo === 'function') { window.TempoApp.navigateTo('community'); } else { window.location.hash = '#community?tab=posts'; } if (window.TempoCommunity && typeof window.TempoCommunity.selectTab === 'function') { window.TempoCommunity.selectTab('posts'); }" \n                            class="px-3.5 py-1 rounded-full bg-[#FCEFE8] hover:bg-[#F8E1D5] text-[#DE8662] text-xs font-bold transition flex items-center space-x-1 cursor-pointer">\n                        <span>${isViLocale() ? 'Xem tất cả' : 'See all'}</span>\n                        <span class="text-xs">&rarr;</span>\n                    </button>"""
repl_rmode_btn = """                    <button type="button" \n                            id="btn-see-all-posts-recovery"\n                            onclick="if (window.TempoApp && typeof window.TempoApp.navigateTo === 'function') { window.TempoApp.navigateTo('community'); } else { window.location.hash = '#community?tab=posts'; } if (window.TempoCommunity && typeof window.TempoCommunity.selectTab === 'function') { window.TempoCommunity.selectTab('posts'); }" \n                            class="px-3.5 py-1 rounded-full bg-[#FCEFE8] hover:bg-[#F8E1D5] text-[#DE8662] text-xs font-bold transition flex items-center space-x-1 cursor-pointer"\n                            aria-label="${isViLocale() ? 'Xem tất cả →' : 'View all →'}" title="${isViLocale() ? 'Xem tất cả →' : 'View all →'}">\n                        <span>${(window.t ? (window.t('modes.recovery.viewAll') || window.t('modes.recovery.seeAll')) : null) || (isViLocale() ? 'Xem tất cả' : 'View all')}</span>\n                        <span class="text-xs">&rarr;</span>\n                    </button>"""
assert target_rmode_btn in content, "target_rmode_btn not found in mode.js"
content = content.replace(target_rmode_btn, repl_rmode_btn, 1)

with open('mode.js', 'w', encoding='utf-8', newline='') as f:
    f.write(content)

print("mode.js updated successfully.")
